WITH filtered AS (SELECT *, ROUND(salary, 1) salary_rounded, COALESCE(level, 'N/A') level_clean FROM employees WHERE hire_date >= DATE '2023-10-05' AND level IS NOT NULL AND level = 'L1') SELECT *, DENSE_RANK() OVER w_running salary_dense_rank, LEAD(salary, 2, 0) OVER (PARTITION BY manager_id, level ORDER BY salary_rounded, id) next_salary FROM filtered WINDOW w_running AS (ORDER BY salary DESC);
